#!/usr/bin/env python3
"""Generate BIEK Computer Science 12th Class Past Paper Analysis Report."""

import csv
import re
from collections import Counter, defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# ── Basic counts ───────────────────────────────────────────────────────────
year_type_counts = defaultdict(lambda: Counter())
for r in rows:
    year_type_counts[int(r["year"])][r["type"]] += 1

years = sorted(year_type_counts.keys())
types = ["MCQs", "Short", "Long"]

# ── KPI calculations ───────────────────────────────────────────────────────
totals_by_year = {}
for y in years:
    totals_by_year[y] = sum(year_type_counts[y].values())

# Year-over-year change
yoy_changes = {}
for i in range(1, len(years)):
    prev = years[i - 1]
    curr = years[i]
    abs_change = totals_by_year[curr] - totals_by_year[prev]
    pct_change = (abs_change / totals_by_year[prev]) * 100 if totals_by_year[prev] else 0
    yoy_changes[curr] = {"abs": abs_change, "pct": round(pct_change, 1)}

# Averages per type
avg_by_type = {}
for t in types:
    vals = [year_type_counts[y][t] for y in years]
    avg_by_type[t] = round(sum(vals) / len(vals), 1)

# Overall totals
overall_by_type = {}
for t in types:
    overall_by_type[t] = sum(year_type_counts[y][t] for y in years)
grand_total = sum(overall_by_type.values())

# ── Topic / keyword analysis ──────────────────────────────────────────────
# Define topic categories with keywords
topic_keywords = {
    "C Data Types & Variables": [
        "data type", "variable", "constant", "identifier", "int ", "float ",
        "char ", "double", "reserved word", "keyword", "size of", "bytes",
        "type casting", "storage class", "global variable", "local variable",
        "external variable", "integer", "declaration"
    ],
    "Operators": [
        "operator", "arithmetic", "relational operator", "logical operator",
        "assignment operator", "increment", "decrement", "bitwise",
        "ternary", "precedence", "unary operator", "&&", "||",
