    "Loops": [
        "loop", "for loop", "while loop", "do-while", "do while",
        "nested loop", "iteration", "nested for"
    ],
    "Functions": [
        "function", "recursion", "recursive", "prototype", "parameter",
        "argument", "return statement", "call by value", "call by reference",
        "user-defined", "library function", "void", "main()", "invokes itself"
    ],
    "Arrays & Strings": [
        "array", "string", "strlen", "string.h"
    ],
    "Pointers & Structures": [
        "pointer", "structure", "union", "address"
    ],
    "File Handling": [
        "file", "fclose", "fscanf", "data file", "file opening mode",
        "file handling", "file operation"
    ],
    "DBMS Fundamentals": [
        "dbms", "database management", "database administrator", "dba",
        "data dictionary", "normalization", "normal form", "data redundancy",
