    ],
    "SQL": [
        "sql", "dml", "ddl", "dcl", "tcl", "data manipulation language",
        "data definition language", "data control language", "transaction control"
    ],
    "MS Access": [
        "ms access", "ms-access", "microsoft access", "table", "query",
        "form", "report", "macro", "module", "object", "data type in ms",
        "vba"
    ],
    "Programming Errors": [
        "error", "syntax error", "logical error", "runtime", "debug",
        "compiler", "interpreter", "source code", "object code", "linker"
    ],
}

# Count topic occurrences by year and overall
