# ── Topic frequency by year (for heatmap) ──────────────────────────────────
top_topics = [t for t, _ in sorted_topics[:10]]

# ── Build HTML ─────────────────────────────────────────────────────────────

# Year labels for charts
year_labels = [str(y) for y in years]

