short_data = [year_type_counts[y]["Short"] for y in years]
long_data = [year_type_counts[y]["Long"] for y in years]
totals_data = [totals_by_year[y] for y in years]

# Topic chart data
topic_labels = [t for t, _ in sorted_topics[:12]]
topic_values = [v for _, v in sorted_topics[:12]]

# Specific concept chart data
spec_labels = [t for t, _ in sorted_specifics]
spec_values = [v for _, v in sorted_specifics]

