    "Variables & Identifiers": r"\bvariable\b|\bidentifier\b|\bconstant\b|\breserved word\b",
    "Pointers & Structures": r"\bpointer\b|\bstructure\b|\bunion\b",
    "File Handling": r"\bfile\b|\bfclose\b|\bfopen\b",
    "I/O Functions (printf/scanf)": r"\bprintf\b|\bscanf\b|\bgetch\b|\bgets\b",
